Path('/output/fit_source.py').write_text('''import numpy as np
D=np.load('/challenge/observations.npz');X=D['tokens'];Y=D['probabilities']
def sm(a):
 a=a-a.max(axis=-1,keepdims=True);a=np.exp(a);return a/a.sum(axis=-1,keepdims=True)
def forward(par,x,grad=False,y=None,decay=1.):
 pi,U,E,A=[sm(a) for a in par];N,L=x.shape;K=len(pi);z=np.broadcast_to(par[0],(N,K)).copy();bs=[];es=[];qs=[]
 for t in range(L):
  b=sm(z);e=np.broadcast_to(E,(N,K,16)) if t==0 else A[:,x[:,t-1]].transpose(1,0,2)
  q=np.einsum('nk,nkv->nv',b,e);bs.append(b);es.append(e);qs.append(q)
  z=decay*z+np.log(U[:,x[:,t]].T)
 q=np.stack(qs,1)
 if not grad:return q
 loss=np.sum(y*np.log(y/q))/N/L;gU=np.zeros_like(U);gE=np.zeros_like(E);gA=np.zeros_like(A);dz=np.zeros((N,K))
 for t in range(L-1,-1,-1):
  if t<L-1:
   for a in range(16):gU[:,a]+=dz[x[:,t]==a].sum(0)
   dz=decay*dz
  b=bs[t];e=es[t];dq=-y[:,t]/q[:,t]/N/L
  db=np.einsum('nv,nkv->nk',dq,e);dz+=b*(db-(db*b).sum(1,keepdims=True))
  de=b[:,:,None]*dq[:,None,:]
  if t==0:gE+=de.sum(0)
  else:
   for a in range(16):gA[:,a]+=de[x[:,t-1]==a].sum(0)
 gp=dz.sum(0)
 gr=[gp,gU-U*gU.sum(-1,keepdims=True),E*(gE-(gE*E).sum(-1,keepdims=True)),A*(gA-(gA*A).sum(-1,keepdims=True))]
 return loss,gr
def fit(K,iters=1200,seed=1,train=np.arange(96),init=None,rate=.03,decay=1.):
 rng=np.random.default_rng(seed);mean=Y[train].mean((0,1))
 if init is None:
  e=np.log(mean)[None,:]+rng.normal(0,.5,(K,16));par=[np.zeros(K),e.copy(),e.copy(),np.broadcast_to(e[:,None,:],(K,16,16)).copy()+np.eye(16)[None,:,:]*.6]
 else:par=[a.copy() for a in init]
 m=[np.zeros_like(a) for a in par];v=[np.zeros_like(a) for a in par];best=1e9;bestpar=None
 for i in range(1,iters+1):
  loss,gr=forward(par,X[train],True,Y[train],decay)
  for j in range(len(par)):
   m[j]=.9*m[j]+.1*gr[j];v[j]=.999*v[j]+.001*gr[j]**2
   par[j]-=rate*(m[j]/(1-.9**i))/(np.sqrt(v[j]/(1-.999**i))+1e-8)
  if i%100==0 or i==iters:
   q=forward(par,X[96:],decay=decay);val=np.mean(np.sum(Y[96:]*np.log(Y[96:]/q),-1))
   if val<best:best=val;bestpar=[a.copy() for a in par]
 return bestpar,loss,best
''')
